INSERT INTO "public"."phong" ("id", "nha_tro_id", "ten", "khu_vuc", "tang", "dien_tich", "so_nguoi_toi_da", "trang_thai", "gia_hien_tai", "tien_coc_mac_dinh", "mo_ta", "tao_luc", "cap_nhat_luc", "xoa_luc", "tang_id", "version") VALUES (E'acd7eb9a-4e0e-4056-91f1-50e0b8881240', E'3c21cb2b-21aa-428d-9991-0c320a951eef', E'PHÒNG 101', E'', E'1', E'20.00', E'4', E'AVAILABLE', E'3500000.00', E'3500000.00', E'Phòng studio thiết kế hiện đại với diện tích 20m², không gian thoáng đãng và tối ưu cho sinh hoạt cá nhân hoặc cặp đôi. Phòng được trang bị đầy đủ nội thất gồm giường 1m8, tủ quần áo lớn, bàn làm việc, điều hòa 2 chiều, tủ lạnh, máy giặt riêng và bình nóng lạnh. Khu vực bếp mini bố trí gọn gàng với tủ bếp và bếp từ tiện lợi.\n\nPhòng có cửa sổ lớn và ban công riêng, đón ánh sáng tự nhiên và lưu thông không khí tốt, mang lại cảm giác thoải mái và dễ chịu. Nhà vệ sinh khép kín sử dụng thiết bị vệ sinh hiện đại, sạch sẽ và riêng tư.\n\nTòa nhà được trang bị wifi tốc độ cao, camera an ninh 24/7, khóa vân tay và chỗ để xe rộng rãi, đảm bảo an toàn và thuận tiện cho người thuê. Vị trí nằm gần trường học, chợ, siêu thị và các tuyến giao thông chính, phù hợp cho sinh viên, nhân viên văn phòng hoặc người làm việc tại trung tâm thành phố.', E'2026-05-27 02:00:54.460465+00', E'2026-06-01 06:58:55.722708+00', NULL, E'158b692a-46d0-4463-814c-9d580ab7e22e', E'0');
