INSERT INTO "public"."phong" ("id", "nha_tro_id", "ten", "khu_vuc", "tang", "dien_tich", "so_nguoi_toi_da", "trang_thai", "gia_hien_tai", "tien_coc_mac_dinh", "mo_ta", "tao_luc", "cap_nhat_luc", "xoa_luc", "tang_id", "version") VALUES (E'f776bab1-2a8e-411e-823d-fa16270da89e', E'3c21cb2b-21aa-428d-9991-0c320a951eef', E'PHÒNG 103', E'', E'1', E'24.00', E'2', E'RENTED', E'2900000.00', E'2900000.00', E'Phòng diện tích 24m² có thiết kế gác lửng giúp tối ưu diện tích sử dụng. Không gian sạch sẽ, thông thoáng với điều hòa, quạt trần, wifi tốc độ cao và nhà vệ sinh khép kín. Gác ngủ riêng tạo cảm giác rộng rãi và riêng tư.\n\nKhu trọ gần trường đại học, siêu thị mini và các tuyến xe buýt thuận tiện cho việc học tập và đi làm.', E'2026-05-27 02:10:42.795126+00', E'2026-06-01 06:58:55.722708+00', NULL, E'158b692a-46d0-4463-814c-9d580ab7e22e', E'0');
