INSERT INTO "public"."hop_dong" ("id", "phong_id", "khach_thue_id", "ma_hop_dong", "ngay_bat_dau", "ngay_ket_thuc", "ngay_ket_thuc_thuc_te", "gia_thue_hop_dong", "tien_coc", "trang_thai_coc", "trang_thai", "chu_ky_thanh_toan", "ngay_thanh_toan_hang_thang", "tu_dong_gia_han", "chi_so_dien_ban_dau", "chi_so_nuoc_ban_dau", "noi_dung_hop_dong", "file_pdf", "ghi_chu", "tao_luc", "cap_nhat_luc", "xoa_luc", "template_version", "previewed_at", "confirmed_at", "locked_at", "signed_pdf_url", "tenant_signed_at", "landlord_signed_at", "signature_status") VALUES (E'b797e88b-a0f1-4b56-8ca7-6a6da5c0240f', E'e30e4555-7e6c-4c7b-8cdf-c8c57145c75d', E'cdbe66ce-3bf0-4023-b2c8-38ba477730f1', E'HD003', E'2026-05-24', E'2026-08-24', NULL, E'3000000.00', E'1000000.00', E'NOT_PAID', E'PENDING', E'MONTHLY', E'15', E'f', E'0', E'0', E'ĐIỀU KHOẢN HỢP ĐỒNG THUÊ PHÒNG\n\n1. BÊN CHO THUÊ (Chủ nhà):\n- Cung cấp phòng ở đầy đủ tiện nghi theo thỏa thuận\n- Đảm bảo an ninh, an toàn cho khách thuê\n- Bảo trì, sửa chữa các hư hỏng do hao mòn tự nhiên\n\n2. BÊN THUÊ (Khách thuê):\n- Thanh toán đúng hạn tiền thuê và các chi phí khác\n- Sử dụng phòng đúng mục đích, giữ gìn vệ sinh\n- Không được cải tạo, sửa chữa phòng mà không có sự đồng ý\n- Báo cáo kịp thời các hư hỏng, sự cố\n\n3. ĐIỀU KHOẢN CHUNG:\n- Thời hạn hợp đồng: Từ ngày bắt đầu đến ngày kết thúc\n- Tiền cọc: Được hoàn trả khi kết thúc hợp đồng (trừ các khoản phát sinh)\n- Thanh toán: Hàng tháng vào ngày quy định\n- Điện, nước: Tính theo chỉ số đồng hồ và giá quy định\n- Phí dịch vụ: Theo thỏa thuận riêng\n\n4. CHẤM DỨT HỢP ĐỒNG:\n- Bên thuê có thể chấm dứt hợp đồng trước thời hạn với thông báo trước 30 ngày\n- Bên cho thuê có thể chấm dứt hợp đồng nếu vi phạm nghiêm trọng\n- Hoàn trả tiền cọc sau khi kiểm tra tình trạng phòng\n\n5. ĐIỀU KHOẢN KHÁC:\n- Hai bên cam kết thực hiện đúng các điều khoản đã thỏa thuận\n- Mọi tranh chấp sẽ được giải quyết thông qua thương lượng\n- Hợp đồng có hiệu lực kể từ ngày ký', NULL, NULL, E'2026-05-24 06:09:39.143652+00', E'2026-05-27 02:11:55.55544+00', E'2026-05-27 02:11:54.039362+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, E'UNSIGNED');
